#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=4

SIREN="980207898"
SIRET="98020789800050"
ENV_FILE="docs/conformite/facturation-electronique.env"
mkdir -p docs/conformite

banner "ouvrance — plateforme agréée de facturation électronique"

# ──────────────────────────────────────────────────────────────────────────
stage "Choisir la plateforme agréée"
say "Depuis le 1er septembre 2026, toute entreprise assujettie doit pouvoir"
say "RECEVOIR une facture électronique via une plateforme agréée — même sans"
say "aucune opération dans le champ (FAQ DGFiP 1.2). L'échéance est passée."
printf '\n'
say "Recommandation : INDY. Gratuit sans limite d'usage, couvre réception,"
say "émission et e-reporting, et n'oblige à souscrire aucun autre produit."
note "Alternative équivalente : TIIME, également gratuite. Les deux sont"
note "immatriculées. Le choix est réversible : on change de plateforme dans"
note "l'annuaire quand on veut."
printf '\n'
warn "Stripe n'est PAS plateforme agréée — vérifié sur la liste officielle."
printf '\n'
step "La liste officielle DGFiP s'ouvre : tu peux y retrouver la plateforme"
step "que tu choisis (149 immatriculées, 16 en attente de test d'interop)."
open_url "https://www.impots.gouv.fr/liste-des-plateformes-de-dematerialisation-partenaires-pdp-immatriculees-sous-reserve"
pause "Liste ouverte ?"
ask PA_NOM "Nom de la plateforme retenue [Indy] :"
[[ -z "$PA_NOM" ]] && PA_NOM="Indy"
write_env PA_NOM "$PA_NOM"

# ──────────────────────────────────────────────────────────────────────────
stage "Créer le compte et signer le mandat de désignation"
say "C'est la plateforme qui t'inscrit à l'annuaire de l'État — tu n'as aucune"
say "démarche à faire auprès de la DGFiP. Elle a besoin du mandat pour ça."
printf '\n'
step "Crée le compte avec l'identité de l'entreprise, pas un compte perso."
step "Raison sociale à saisir : EI Fayssal BENOUDA (la mention « EI » est"
step "  obligatoire, article R526-27 du Code de commerce)."
step "SIREN  : $SIREN"
step "SIRET  : $SIRET"
step "Signe le MANDAT DE DÉSIGNATION quand il est proposé — sans lui, tu"
step "  n'apparais pas dans l'annuaire et l'obligation n'est pas remplie."
printf '\n'
if [[ "${PA_NOM,,}" == "tiime" ]]; then
  open_url "https://www.tiime.fr/facturation-electronique"
else
  open_url "https://www.indy.fr/facturation-electronique/"
fi
pause "Compte créé et mandat signé ?"
ask PA_DATE_INSCRIPTION "Date de l'inscription (AAAA-MM-JJ) [$(date +%F)] :"
[[ -z "$PA_DATE_INSCRIPTION" ]] && PA_DATE_INSCRIPTION="$(date +%F)"
write_env PA_DATE_INSCRIPTION "$PA_DATE_INSCRIPTION"

# ──────────────────────────────────────────────────────────────────────────
stage "Vérifier le rattachement dans l'annuaire"
say "L'annuaire de l'État est le registre qui dit, pour chaque SIREN, quelle"
say "plateforme reçoit ses factures. La consultation est gratuite et ne demande"
say "aucun compte."
printf '\n'
warn "Le rattachement n'est pas instantané : la plateforme le déclare, l'annuaire"
warn "le publie. Si tu ne te vois pas encore, ce n'est pas un échec — reviens"
warn "plus tard et relance ce wizard, il retient ce qui est déjà saisi."
printf '\n'
step "Sur le portail Chorus Pro, ouvre « Annuaire de la facturation"
step "  électronique » et cherche le SIREN $SIREN."
step "Ce qu'il faut voir : l'entreprise trouvée, rattachée à une plateforme,"
step "  avec une adresse de réception active."
note "Le NOM de la plateforme n'est pas visible du public (secret des affaires) :"
note "voir « rattachée » suffit."
open_url "https://portail.chorus-pro.gouv.fr"
open_url "https://portail.chorus-pro.gouv.fr/aife_documentation?id=kb_article_view&sysparm_article=KB0012174"
pause "Annuaire consulté ?"
if confirm "Le SIREN $SIREN apparaît-il rattaché à une plateforme ?"; then
  ANNUAIRE_STATUT="rattaché"
  ANNUAIRE_VERIFIE_LE="$(date +%F)"
else
  ANNUAIRE_STATUT="en attente de publication"
  ANNUAIRE_VERIFIE_LE="$(date +%F)"
  SKIPPED+=("revérifier l'annuaire dans quelques jours : relance ce wizard")
fi
write_env ANNUAIRE_STATUT "$ANNUAIRE_STATUT"
write_env ANNUAIRE_VERIFIE_LE "$ANNUAIRE_VERIFIE_LE"

# ──────────────────────────────────────────────────────────────────────────
stage "Déposer la preuve datée"
say "L'échéance étant dépassée, ce qui te protège n'est pas d'être en règle"
say "au jour dit — c'est de pouvoir DÉMONTRER une trajectoire sérieuse."
printf '\n'
note "Guide pratique DGFiP, verbatim : « Cette approche ne constitue ni un"
note "report ni une suspension de l'obligation. » et « L'entreprise doit"
note "pouvoir démontrer qu'elle a engagé les démarches nécessaires. »"
printf '\n'
PREUVE="docs/conformite/facturation-electronique.md"
cat > "$PREUVE" <<EOF
# Facturation électronique — trace des démarches

Entité : **EI Fayssal BENOUDA** — SIREN $SIREN, SIRET $SIRET.
Obligation : **recevoir** une facture électronique via une plateforme agréée,
échue au **1er septembre 2026** (FAQ DGFiP 1.2 — l'obligation vaut même sans
aucune opération dans le champ).

| Démarche | Date | État |
| --- | --- | --- |
| Plateforme agréée retenue | $PA_DATE_INSCRIPTION | **$PA_NOM** |
| Compte créé, mandat de désignation signé | $PA_DATE_INSCRIPTION | fait |
| Rattachement vérifié à l'annuaire | $ANNUAIRE_VERIFIE_LE | **$ANNUAIRE_STATUT** |

Vérification de l'annuaire : portail Chorus Pro, consultation libre par SIREN,
sans compte.

## Les échéances suivantes

- **1er janvier 2027** — le délai de conservation de l'article L102 B du LPF
  passe de six à dix ans.
- **1er septembre 2027** — obligation d'**émettre** en facture électronique
  (micro-entreprises), et obligation d'**e-reporting**. Les ventes aux Offrants
  sont du B2C : elles ne relèvent **jamais** de la facturation électronique,
  seulement de l'e-reporting, en fréquence **bimestrielle** sous franchise en
  base.

Établi par le wizard \`scripts/plateforme-agreee.sh\`, ticket #53.
Sources et raisonnement : [La facture d'une Commande](https://github.com/fayssalbenouda936/ouvrance/issues/36).
EOF
printf '  %s✓ écrit%s %s\n' "$GREEN" "$RESET" "$PREUVE"
printf '\n'
step "Relis le fichier, puis committe-le : c'est lui la preuve."
note "git add $PREUVE $ENV_FILE && git commit -m \"Trace la désignation de la plateforme agréée (#53)\""

finish
